import codecs, hashlib, json, struct, sys, unicodedata
assert sys.version_info[:3] == (3, 14, 7)
assert unicodedata.unidata_version == '16.0.0'
assert sys.platform == 'darwin' and sys.byteorder == 'little'

def digest(rows):
    h = hashlib.sha256()
    for row in rows:
        h.update((json.dumps(row, separators=(',', ':'), ensure_ascii=True) + '\n').encode())
    return h.hexdigest()

def failure(e):
    return ['error', e.encoding, list(e.object), e.start, e.end, e.reason]

def decode_rows(errors):
    for first in range(128, 256):
        for second in range(256):
            try:
                text, consumed = codecs.getdecoder('euc_jp')(bytes([first, second]), errors)
                yield ['ok', list(map(ord, text)), consumed]
            except UnicodeDecodeError as e:
                yield failure(e)

def state(d):
    pending, flags = d.getstate()
    return [list(pending), str(flags)]

def call(d, data, final):
    try:
        result = ['ok', list(map(ord, d.decode(data, final)))]
    except UnicodeDecodeError as e:
        result = failure(e)
    return [result, state(d)]

def split_row(data, split, final, errors):
    d = codecs.getincrementaldecoder('euc_jp')(errors)
    d.setstate((b'', 0x123456789abcdef0))
    row = [call(d, data[:split], False), call(d, data[split:], final), call(d, b'', True)]
    d.reset()
    row.append(state(d))
    return row

def incremental_rows(errors):
    for first in range(256):
        for second in range(256):
            for final in (False, True):
                yield split_row(bytes([first, second]), 1, final, errors)

result = {
    'reference': {'version': sys.version, 'unicode': unicodedata.unidata_version, 'platform': sys.platform, 'byteorder': sys.byteorder},
    'decode': {p: {'records':32768, 'sha256':digest(decode_rows(p))} for p in ('strict', 'ignore', 'replace')},
    'incremental': {p: {'records':131072, 'sha256':digest(incremental_rows(p))} for p in ('strict', 'ignore', 'replace')},
    'encode': {}
}
text = ''.join(map(chr, range(0x110000)))
for p in ('ignore', 'replace'):
    data = text.encode('euc_jp', p)
    result['encode'][p] = {'length':len(data), 'sha256':hashlib.sha256(data).hexdigest()}
# Strict singletons preserve exact fault metadata and every successful spelling.
def encodings(start=0, end=0x110000):
    for point in range(start, end):
        try:
            yield ['ok', list(chr(point).encode('euc_jp'))]
        except UnicodeEncodeError as e:
            yield ['error', e.encoding, list(map(ord,e.object)), e.start, e.end, e.reason]
result['strictEncode'] = {'records':0x110000, 'sha256':digest(encodings())}
result['strictEncode']['planes'] = [digest(encodings(p*0x10000, (p+1)*0x10000)) for p in range(17)]

def triples(errors, block):
    for second in range(block*16, (block+1)*16):
        for third in range(256):
            for split in range(4):
                for final in (False, True):
                    yield split_row(bytes([0x8f, second, third]), split, final, errors)
result['triples'] = {p:[digest(triples(p,b)) for b in range(16)] for p in ('strict','ignore','replace')}

print(json.dumps(result, indent=2))

