import codecs, hashlib, json
rows = []
for original in [b'', b'\xa1', b'ABC\xa1']:
    for pending in [b'', b'Z', b'12345678']:
        for final in [False, True]:
            for action in ['end', 'negative', 'rewind', 'out-of-bounds', 'raise', 'reset', 'nested']:
                seen = []
                failure = ValueError('guest failure')
                decoder = codecs.getincrementaldecoder('euc_jp')('decoder_matrix')
                def handler(error):
                    seen.append([error.encoding, list(error.object), error.start, error.end, error.reason])
                    decoder.setstate((pending, 99))
                    if action == 'raise': raise failure
                    if action == 'reset': decoder.reset()
                    if action == 'nested':
                        decoder.setstate((b'X', 123))
                        seen.append(['nested', decoder.decode(b'Y', False)])
                    position = -1 if action == 'negative' else 0 if action == 'rewind' else len(error.object) + 1 if action == 'out-of-bounds' else error.end
                    if error.reason != 'incomplete multibyte sequence' and action in ('negative', 'rewind'):
                        position = error.end
                    return ('?', position)
                codecs.register_error('decoder_matrix', handler)
                decoder.setstate((original, 42))
                try:
                    result = ['ok', list(map(ord, decoder.decode(b'\xff\xa1', final)))]
                except UnicodeDecodeError as error:
                    result = ['error', type(error).__name__, error.encoding, list(error.object), error.start, error.end, error.reason]
                except BaseException as error:
                    result = ['error', type(error).__name__, str(error), error is failure]
                data, state = decoder.getstate()
                rows.append([list(original), list(pending), final, action, seen, result, [list(data), str(state)]])
serialized = ''.join(json.dumps(row, separators=(',', ':'), ensure_ascii=True) + '\n' for row in rows)
print(json.dumps({'records': len(rows), 'sha256': hashlib.sha256(serialized.encode()).hexdigest()}))

